      // The far endpoints are returned only after the complete T/C/D topology checks.
      const [p, q] = collar.far,
        farLength = Math.hypot(q[0] - p[0], q[1] - p[1]);
      if (!Number.isFinite(w) || !Number.isFinite(farLength) || farLength <= EPS) {
        fail(
          'collar-upper-degenerate',
          attachment.id,
          null,
          'finite positive root and validated far lengths',
        );
        continue;
      }
      const farUpper = (farLength + 2 * EPS) / c;
      widthUpper = Math.min(rootUpper, farUpper);
      upperWitness = {
        widthUpperRoot: rootUpper,
        widthUpperFar: farUpper,
        widthUpperWitness: rootUpper <= farUpper ? 'root' : 'far',
      };
    }
