      maximum(role.extentUpper, 0.45, 'peninsula-extent-max', attachment.id);
      maximum(widthUpper, 0.16, 'peninsula-width-max', attachment.id);
      minimum(role.extentWidthRatioLower, 2, 'peninsula-ratio', attachment.id);
    }
