    const bay = candidate.bay,
      [a, b] = bay.mouth;
    const ra = Math.hypot(...a),
      rb = Math.hypot(...b);
    const mouthEdges = edges(bay.polygon).filter(([e, f]) => !sharedEdge(a, b, e, f));
