    { id: 'interior', polygon: candidate.interior, shoulders: true },
    { id: 'body', polygon: candidate.bodyBoundary, shoulders: true },
    ...candidate.attachments.map((p) => ({ ...p, shoulders: false })),
    ...candidate.islands.map((p) => ({ ...p, shoulders: false })),
