  if (
    !Number.isFinite(Math.hypot(...bay.witness)) ||
    Math.hypot(...bay.witness) > chartRadius + EPS
  )
    reject('bay-witness-cap', Math.hypot(...bay.witness), 'inside the measured chart cap');
