    !Array.isArray(owners) ||
    owners.length < 1 ||
    owners.length > 8 ||
    typeof seed !== 'string' ||
    seed.length === 0 ||
    owners.some(
      (owner) =>
        !owner ||
        typeof owner !== 'object' ||
        typeof owner.id !== 'string' ||
        owner.id.length === 0 ||
        !Number.isFinite(owner.radius) ||
        owner.radius <= 0 ||
        owner.radius + EXTENSION_RAD >= Math.PI,
    ) ||
    new Set(owners.map((o) => o.id)).size !== owners.length
