        id: r.probe.input.id,
        seed: r.probe.input.seed,
        failures: r.construction?.failures,
        placementFailures: r.placement?.failures,
        issues: r.issues,
      };
    if (cohort === 'control')
      result.controlFingerprints.push({
        id: r.probe.input.id,
        status: r.status,
        geometry: r.geometryFingerprint,
        placement: r.placementFingerprint,
      });
